"""Offline replay: apply candidate answer rules to every recorded run's predictions."""
import json, glob, os, re, sys, copy
sys.path.insert(0, '/workspace/benchmark')
from benchmark.data.evaluators import eval_uspto, eval_lawbench, eval_symptom2disease

RUNS = sorted(glob.glob('/workspace/runs/*/'))

def load(run):
    rows = [json.loads(l) for l in open(run + 'results/samples.jsonl')]
    mems = {}
    for task in {r['task'] for r in rows}:
        try:
            mems[task] = json.load(open(f'{run}{task}/memory.json'))['examples']
        except FileNotFoundError:
            mems[task] = []
    return rows, mems

def units_from(answers, sep):
    out = []
    for a in answers:
        if sep and sep in a:
            out.extend(p.strip() for p in a.split(sep) if p.strip())
        else:
            out.append(a.strip())
    return out

def score(task, pred, target):
    if task == 'USPTO':
        return eval_uspto(pred, target)['correct']
    if task == 'LawBench':
        return eval_lawbench(pred, target)['correct']
    return eval_symptom2disease(pred, target)

def report(name, rule):
    tot = {'gain': 0, 'loss': 0, 'n': 0}
    per = {}
    for run in RUNS:
        rows, mems = load(run)
        for r in rows:
            if r['status'] != 'ok':
                continue
            mem = [str(e['target']) for e in mems[r['task']]]
            new = rule(r['task'], r['prediction'], mem)
            if new == r['prediction']:
                continue
            before = score(r['task'], r['prediction'], r['target'])
            after = score(r['task'], new, r['target'])
            tot['n'] += 1
            d = per.setdefault(r['task'], {'gain': 0, 'loss': 0})
            if after and not before:
                tot['gain'] += 1; d['gain'] += 1
            elif before and not after:
                tot['loss'] += 1; d['loss'] += 1
    print(f'{name}: changed={tot["n"]} gain={tot["gain"]} loss={tot["loss"]} per-task={per}')
