from collections import Counter

def frag_rule(task, pred, mem):
    """Fragments of dotted answers: a fragment that is a prefix of exactly one memory
    fragment, or that differs from one by a trailing character, becomes that fragment."""
    units = Counter()
    for a in mem:
        for p in a.split('.'):
            p = p.strip()
            if p: units[p] += 1
    if not units: return pred
    terminals = {u[-1] for u in units}
    # only act on predictions that look dotted like the memory's answers
    parts = str(pred).split('.')
    if len(parts) < 1: return pred
    out = []
    for p in parts:
        s = p.strip()
        if s and s not in units:
            longer = [u for u in units if len(u) > len(s) and u.startswith(s)]
            if len(longer) == 1:
                s = longer[0]
            elif len(s) > 2 and s[-1] not in terminals and s[:-1] in units:
                s = s[:-1]
        out.append(s)
    return '.'.join(out)

report('USPTO fragment prefix/terminal', lambda t,p,m: frag_rule(t,p,m) if t=='USPTO' else p)
